import { NextRequest, NextResponse } from 'next/server'
import { PDFDocument, rgb, StandardFonts } from 'pdf-lib'
import QRCode from 'qrcode'

export const runtime = 'nodejs'

// PDF de Arca como plantilla base64 (capa de texto saneada: sin labels duplicados ni glifos recortados)
const TEMPLATE_B64 = ''

const K    = rgb(0, 0, 0)
const W    = rgb(1, 1, 1)  // blanco para cubrir campos
const GRAY2 = rgb(0.3, 0.3, 0.3)

const PH = 842
// Baseline: pdf-lib y = PH - yTop - size
const B = (yTop: number, sz: number) => PH - yTop - sz

// Formato ARCA: coma decimal, SIN separador de miles (el portal parsea este formato)
function fmt(n: number) {
  return n.toFixed(2).replace('.', ',')
}

// Cubrir un área con blanco
function cover(page: any, x: number, yTop: number, w: number, h: number, pad = 2) {
  page.drawRectangle({
    x: x - pad, y: PH - yTop - h - pad,
    width: w + pad * 2, height: h + pad * 2,
    color: W, borderWidth: 0,
  })
}

export async function POST(req: NextRequest) {
  try {
    const { comprobante: c, cuitAseg, dirAseg, razonSocial } = await req.json()

    const nro = String(c.nro_cbte_afip ?? c.numero ?? 0).padStart(8, '0')
    const fecha = (c.fecha || '').split('-').reverse().join('/')
    const vto = c.cae_vencimiento ? c.cae_vencimiento.split('-').reverse().join('/') : ''
    const tipo = c.categoria === 'nc' ? 'NOTA DE CREDITO' : 'FACTURA'
    // Código de tipo de comprobante ARCA (para el nombre de archivo): 001=FA A, 003=NC A, 006=FA B, 008=NC B
    const tipoCode =
      c.tipo === 'A' ? (c.categoria === 'nc' ? '003' : '001')
                     : (c.categoria === 'nc' ? '008' : '006')

    // Cargar plantilla
    const tmplBytes = Buffer.from(TEMPLATE_B64, 'base64')

    const copias = ['ORIGINAL', 'DUPLICADO', 'TRIPLICADO']
    const outDoc = await PDFDocument.create()
    // Metadatos idénticos a los PDFs nativos de ARCA
    outDoc.setCreator('ARCA')
    outDoc.setAuthor('ARCA')
    outDoc.setProducer('iText 2.1.7 by 1T3XT')
    const R  = await outDoc.embedFont(StandardFonts.Helvetica)
    const Bd = await outDoc.embedFont(StandardFonts.HelveticaBold)
    const It = await outDoc.embedFont(StandardFonts.HelveticaOblique)

    for (const copia of copias) {
      // Copiar plantilla con layout exacto de ARCA
      const tmplDoc = await PDFDocument.load(tmplBytes)
      const [tmplPage] = await outDoc.copyPages(tmplDoc, [0])
      outDoc.addPage(tmplPage)
      const p = outDoc.getPage(outDoc.getPageCount() - 1)

      const t = (x: number, yTop: number, s: string, sz: number, bold = false, color = K) =>
        p.drawText(s, { x, y: B(yTop, sz), font: bold ? Bd : R, size: sz, color })

      const tR = (xRight: number, yTop: number, s: string, sz: number, bold = false) => {
        const f = bold ? Bd : R
        p.drawText(s, { x: xRight - f.widthOfTextAtSize(s, sz), y: B(yTop, sz), font: f, size: sz, color: K })
      }

      const tC = (xC: number, yTop: number, s: string, sz: number, bold = false) => {
        const f = bold ? Bd : R
        p.drawText(s, { x: xC - f.widthOfTextAtSize(s, sz)/2, y: B(yTop, sz), font: f, size: sz, color: K })
      }

      // ── COPIA ── (el "ORIGINAL" fijo fue eliminado de la plantilla)
      tC(298, 25, copia, 14, true)

      // ── PUNTO DE VENTA / COMP NRO / FECHA ──
      // Los labels fueron eliminados de la plantilla: se dibujan UNA sola vez,
      // completos y contiguos al valor, para que el parser del portal los lea.
      t(341, 86, 'Punto de Venta: 00006', 9, true)
      t(461, 86, `Comp. Nro: ${nro}`, 9, true)
      t(341, 102, `Fecha de Emisión: ${fecha}`, 9, true)

      // ── PERÍODO FACTURADO / HASTA / FECHA VTO PAGO ── (formato exacto ARCA, con espacios tras ':')
      cover(p, 150, 170, 430, 12, 1)
      t(159, 171, fecha, 10)
      t(232.4, 171, 'Hasta:', 10, true)
      t(232.4 + Bd.widthOfTextAtSize('Hasta:', 10) + 4, 171, fecha, 10)
      {
        const lblVto = 'Fecha de Vto. para el pago: '
        const wF = R.widthOfTextAtSize(fecha, 10)
        const wL = Bd.widthOfTextAtSize(lblVto, 10)
        t(578 - wF - wL, 171, lblVto, 10, true)
        t(578 - wF, 171, fecha, 10)
      }

      // ── RECEPTOR ──
      cover(p, 52, 190, 528, 11, 1)
      t(52, 191, (cuitAseg || '').replace(/-/g,''), 8)
      t(222, 191, 'Apellido y Nombre / Razón Social:', 8, true)
      t(356, 191, (razonSocial || '').slice(0, 46), 8)
      // ── ITEMS ──
      cover(p, 15, 295, 566, 225, 0)

      let iy = 301
      for (const it of (c.items || [])) {
        const net = Math.round((it.p || 0) / 1.21 * 100) / 100
        // Descripción
        t(57, iy, (it.d || '').slice(0, 55), 8)
        // Cantidad
        tC(256, iy, `${Number(it.c || 1).toFixed(2).replace('.', ',')}`, 8)
        // U. medida
        t(285, iy, 'unidades', 8)
        // Precio Unit.
        tR(385, iy, fmt(net), 8)
        // % Bonif
        tR(414, iy, '0,00', 8)
        // Subtotal
        tR(479, iy, fmt(net * (it.c || 1)), 8)
        // Alícuota IVA
        tC(498, iy, '21%', 8)
        // Subtotal c/IVA
        tR(579, iy, fmt((it.c || 1) * (it.p || 0)), 8)

        iy += 18

        // Referencia
        if (c.siniestro || c.patente || c.vehiculo || c.cliente_nombre) {
          const ref = [c.vehiculo, c.patente ? `Pat: ${c.patente}` : null, c.siniestro ? `Sin: ${c.siniestro}` : null, c.cliente_nombre ? c.cliente_nombre.toUpperCase() : null].filter(Boolean).join(' · ')
          p.drawText(ref, { x: 57, y: B(iy + 4, 7), font: It, size: 7, color: GRAY2 })
          iy += 10
        }
      }

      // ── TOTALES ── (formato ARCA: sin separador de miles)
      cover(p, 187, 524, 392, 145, 1)
      t(187, 533, 'Importe Otros Tributos: $', 9)
      t(329.5, 533, '0,00', 9)
      const rows: [string, string, boolean, number][] = [
        ['Importe Neto Gravado: $', fmt(c.neto || 0), true,  553],
        ['IVA 27%: $',              '0,00',           false, 566],
        ['IVA 21%: $',              fmt(c.iva || 0),  false, 579],
        ['IVA 10.5%: $',            '0,00',           false, 592],
        ['IVA 5%: $',               '0,00',           false, 605],
        ['IVA 2.5%: $',             '0,00',           false, 618],
        ['IVA 0%: $',               '0,00',           false, 631],
        ['Importe Otros Tributos: $','0,00',           false, 644],
        ['Importe Total: $',  fmt(c.total || 0),       true,  658],
      ]
      for (const [lbl, val, bold, yRow] of rows) {
        const sz = bold ? 10 : 9
        const f = bold ? Bd : R
        p.drawText(lbl, { x: 498 - f.widthOfTextAtSize(lbl, sz) - 4, y: B(yRow, sz), font: f, size: sz, color: K })
        p.drawText(val, { x: 577 - f.widthOfTextAtSize(val, sz), y: B(yRow, sz), font: f, size: sz, color: K })
      }

      // QR — posición exacta de Arca
      try {
        const qrData = {
          ver: 1,
          fecha: c.fecha,
          cuit: 27242657174,
          ptoVta: 6,
          tipoCmp: c.tipo === 'A' ? 1 : c.tipo === 'B' ? 6 : 11,
          nroCmp:     Number(c.nro_cbte_afip ?? c.numero ?? 0),
          importe:    Number(c.total  || 0),
          moneda: 'PES',
          ctz: 1,
          tipoDocRec: 80,
          nroDocRec:  Number((cuitAseg || '0').replace(/-/g, '')),
          tipoCodAut: 'E',
          codAut:     Number(c.cae_emitido || '0'),
        }
        const qrUrl = 'https://www.arca.gob.ar/fe/qr/?p=' + Buffer.from(JSON.stringify(qrData)).toString('base64')
        // ECC 'L' y scale entero (5px por módulo) como ARCA: sin anti-aliasing fraccional,
        // decodifica en cualquier lector. Dibujado 80x80pt en la posición del QR original.
        const qrBuf = await QRCode.toBuffer(qrUrl, { type: 'png', scale: 5, margin: 4, errorCorrectionLevel: 'L' })
        const qrEmbed = await outDoc.embedPng(new Uint8Array(qrBuf))
        p.drawImage(qrEmbed, { x: 20, y: 55, width: 80, height: 80 })
      } catch (e) { /* QR opcional */ }

      // ── CAE ── (labels eliminados de la plantilla; se escriben completos, un espacio tras ':')
      if (c.cae_emitido) {
        t(442.6, 717, `CAE N°: ${c.cae_emitido}`, 10, true)
        t(374.4, 731, `Fecha de Vto. de CAE: ${vto}`, 10, true)
      }
    }

    const bytes = await outDoc.save()
    return new NextResponse(Buffer.from(bytes), {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="27242657174_${tipoCode}_00006_${nro}.pdf"`,
      },
    })
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 })
  }
}
